          names: "item",
          value: '[["Wheat Seeds", "Wheat", "Wheat", 5, 8, 10], ["Carrot Seeds", "Carrot Plant", "Carrot", 15, 30, 20], ["Potato Seeds", "Potato Plant", "Raw Potato", 40, 90, 40], ["Beetroot Seeds", "Beetroot Plant", "Beetroot", 100, 260, 70]]',
